    // 일단 JSON 로드 버전은 사용하지 않는다
    private void loadStage(Context context, int stage) {
        AssetManager assets = context.getAssets();
        try {
            String file = String.format("stage_%02d.tmj", stage);
            InputStream is = assets.open(file);
            InputStreamReader jsr = new InputStreamReader(is);
            JsonReader jr = new JsonReader(jsr);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
    @Override
    public void update() {
        // x 는 화면의 어디에까지 만들었나를 기억한다. SPEED 가 음수이므로 시간에 따라 감소한다
        x += MapObject.SPEED * GameView.frameTime;
        while (x < Metrics.width) {
            createColumn();
            index++;
            x += 100f;
        }
    }
    private void createColumn() {
        for (int row = 0; row < STAGE_HEIGHT; row++) {
            int tile = getAt(index, row); // 알아내서
            float y = 100 * row;
            createObject(tile, x, y); // 생성한다
        }
    }
    private void createObject(int tile, float left, float top) {
        // 젤리 타일인 경우
        if (1 <= tile && tile <= 60) {
            JellyItem item = JellyItem.get(tile - 1, left, top);
            scene.add(MainScene.Layer.item, item);
            return;
        }

        // 플랫폼 타일인 경우.
        if (tile == 61 || tile == 71 || tile == 73) {
            Floor.Type ptype =
                    tile == 61 ? Floor.Type.T_10x2 :
                    tile == 71 ? Floor.Type.T_2x2 :
                                 Floor.Type.T_3x1;
            Floor floor = Floor.get(ptype, left, top);
            scene.add(MainScene.Layer.floor, floor);
            return;
        }
    }

    private int getAt(int col, int row) {
        int idx = row * STAGE_WIDTH + col;
        if (idx >= STAGES[0].length) return 0;
        return STAGES[0][idx]; // STAGES[0] 이 1번째 스테이지 이다
    }
    @Override
    public void draw(Canvas canvas) {}
